    id: bytes
    """Trailer identifier for code. Bytes, decode with `.decode("utf-8", "replace")`."""
    cargo_accessory_id: bytes
    """Identifier of the cargo accessory (the load) of the trailer. Bytes, decode with `.decode("utf-8", "replace")`."""
    brand_id: bytes
    """Brand identifier for code. Bytes, decode with `.decode("utf-8", "replace")`."""
    brand: bytes
    """Brand name for display. Bytes, decode with `.decode("utf-8", "replace")`."""
    name: bytes
    """Trailer name for display. Bytes, decode with `.decode("utf-8", "replace")`."""
    chain_type: bytes
    """Chain type of the trailer combination. Only reported for the first trailer. Bytes, decode with `.decode("utf-8", "replace")`."""
    body_type: bytes
