class Events(ctypes.Structure):
    """Gameplay events. Each entry keeps the payload of the last occurrence, detect a new occurrence by a change of its count."""

    job_delivered: JobDeliveredEvent
    """Last delivered job."""
    job_cancelled: JobCancelledEvent
    """Last cancelled job."""
    fined: FinedEvent
    """Last fine."""
    tollgate: TollgateEvent
    """Last paid tollgate."""
    ferry: FerryEvent
    """Last used ferry."""
    train: TrainEvent
    """Last used train."""

    _fields_ = [
        ("job_delivered", JobDeliveredEvent),
        ("job_cancelled", JobCancelledEvent),
        ("fined", FinedEvent),
        ("tollgate", TollgateEvent),
        ("ferry", FerryEvent),
        ("train", TrainEvent),
    ]


class Substances(ctypes.Structure):
    """Surface types the game knows. wheels[].substance indexes into ids."""

    count: int
    """Number of valid entries in ids."""
    ids: Sequence[Any]
    """Identifier of each substance, for example "road" or "grass". Longer names are truncated. Each entry is a c_char array, read it with `.value` (bytes)."""

    _fields_ = [
        ("count", ctypes.c_uint32),
        ("ids", (ctypes.c_char * 32) * 64),
    ]


class TelemetryData(ctypes.Structure):
    """Everything the plugin publishes. One consistent copy exists per game frame."""

    game: Game
    """State of the game and its clocks."""
    truck: Truck
    """The truck the player drives."""
    trailers: Sequence[Trailer]
    """Trailers, index 0 is the first trailer."""
    job: Job
    """The active job."""
    events: Events
    """Gameplay events."""
    substances: Substances
    """Surface types."""

    _fields_ = [
        ("game", Game),
        ("truck", Truck),
        ("trailers", Trailer * 10),
        ("job", Job),
        ("events", Events),
        ("substances", Substances),
        ("_pad0", ctypes.c_uint8 * 4),
    ]

